/* Normaliza datos del lead entrante */
const body = items[0].json;

const leadData = body.lead_data || body;
const toNumber = body.to_number || leadData.telefono || leadData.TELEFONO;
const callObjective = body.call_objective || 'agendar_visita';

const normalized = {
  nombre: leadData.nombre || leadData.NOMBRE || leadData['NOMBRE '] || '',
  telefono: toNumber,
  propiedad: leadData.propiedad || leadData.PROPIEDAD || '',
  tipo_propiedad: leadData.tipo_propiedad || leadData['TIPO PROPIEDAD'] || '',
  tipo_operacion: leadData.tipo_operacion || leadData['TIPO_OPERACION'] || 'venta',
  valor_uf: leadData.valor_uf || leadData['VALOR UF'] || '',
  tipo_moneda: leadData.tipo_moneda || leadData['tipo moneda'] || 'UF',
  ubicacion: leadData.ubicacion || leadData.UBICACION || '',
  direccion: leadData.direccion || leadData.DIRECCION || '',
  dormitorios: leadData.dormitorios || leadData.DORMITORIOS || '',
  banos: leadData.banos || leadData.BANOS || '',
  m2_totales: leadData.m2_totales || leadData['M2 TOTALES'] || leadData['M2 CONSTRUIDOS'] || '',
  resumen: leadData.resumen || leadData.RESUMEN || '',
  informe: leadData.informe || leadData.INFORME || '',
  tipo_interes: leadData.tipo_interes || leadData['TIPO INTERES'] || leadData.PROPOSITO || '',
  call_objective: callObjective,
  broker_name: 'LexHouse',
  agent_instructions: 'instrucciones_estandar'
};

return [{ json: { ...body, lead_data: normalized, to_number: toNumber } }];

const response = items[0].json;

if (response.error) {
  return [{ json: { success: false, error: response.error, code: response.code, details: response.details } }];
}

return [{ json: {
  success: true,
  call_id: response.call_id,
  elevenlabs_conversation_id: response.elevenlabs_conversation_id,
  voz_log_id: response.voz_log_id,
  remaining_minutes: response.remaining_minutes,
  dynamic_variables_sent: response.dynamic_variables_sent
} }];
